import * as React from 'react';
import {useTranslation} from 'react-i18next';
import {IconIndentDecrease, IconIndentIncrease} from '@tabler/icons';
import {IconButton} from '../control/icon-button';

export interface IndentButtonsProps {
	/**
	 * CodeMirror instance to interact with.
	 */
	editor?: CodeMirror.Editor;
}

export const IndentButtons: React.FC<IndentButtonsProps> = props => {
	const {editor} = props;
	const {t} = useTranslation();

	function execCommand(command: string) {
		editor?.execCommand(command);
		editor?.focus();
	}

	return (
		<>
			<IconButton
				disabled={!editor}
				icon={<IconIndentIncrease />}
				label={t('components.indentButtons.indent')}
				onClick={() => execCommand('indentMore')}
			/>
			<IconButton
				disabled={!editor}
				icon={<IconIndentDecrease />}
				label={t('components.indentButtons.unindent')}
				onClick={() => execCommand('indentLess')}
			/>
		</>
	);
};

src/components/codemirror/undo-redo-butt:
import * as React from 'react';
import {useTranslation} from 'react-i18next';
import {IconArrowBack, IconArrowForward} from '@tabler/icons';
import {IconButton} from '../control/icon-button';

export interface UndoRedoButtonsProps {
	/**
	 * Disables both buttons no matter the state of the editor.
	 */
	disabled?: boolean;
	/**
	 * CodeMirror instance to interact with.
	 */
	editor?: CodeMirror.Editor;
	/**
	 * A change in this prop triggers a render (probably, put the editor value
	 * here). This is necessary because the editor instance itself is mutable, so
	 * we need some way of knowing when to re-check whether undo/redo is availble.
	 */
	watch: string;
}

export const UndoRedoButtons: React.FC<UndoRedoButtonsProps> = props => {
	const {disabled, editor, watch} = props;
	const {t} = useTranslation();
	const [canRedo, setCanRedo] = React.useState(false);
	const [canUndo, setCanUndo] = React.useState(false);

	React.useEffect(() => {
		if (editor) {
			const history = editor.historySize();

			setCanRedo(history.redo > 0);
			setCanUndo(history.undo > 0);
		} else {
			setCanRedo(false);
			setCanUndo(false);
		}
	}, [editor, watch]);

	function execCommand(command: string) {
		editor?.execCommand(command);
		editor?.focus();
	}

	return (
		<>
			<IconButton
				disabled={disabled || !canUndo}
				icon={<IconArrowBack />}
				label={t('common.undo')}
				onClick={() => execCommand('undo')}
			/>
			<IconButton
				disabled={disabled || !canRedo}
				icon={<IconArrowForward />}
				label={t('common.redo')}
				onClick={() => execCommand('redo')}
			/>
		</>
	);
};

