// Independent standard vector/projection arithmetic for the local Twine adaptation.
// SPDX-License-Identifier: GPL-3.0-or-later
// Not copied from segseg, Graphics Gems, or the cited Stack Overflow/gist source.
export default function intersection(output, a, b, c, d) {
  const ab = [b[0] - a[0], b[1] - a[1]];
  const cd = [d[0] - c[0], d[1] - c[1]];
  const ca = [c[0] - a[0], c[1] - a[1]];
  const cross = (v, w) => v[0] * w[1] - v[1] * w[0];
  const determinant = cross(ab, cd);
  if (determinant !== 0) {
    const alongAB = cross(ca, cd) / determinant;
    const alongCD = cross(ca, ab) / determinant;
    if (alongAB >= 0 && alongAB <= 1 && alongCD >= 0 && alongCD <= 1) {
      output[0] = a[0] + alongAB * ab[0];
      output[1] = a[1] + alongAB * ab[1];
      return 1;
    }
  }
  // Preserve the selected package's one-coordinate-unit endpoint proximity policy.
  for (const [point, start, end] of [[a, c, d], [b, c, d], [c, a, b], [d, a, b]]) {
    const dx = end[0] - start[0], dy = end[1] - start[1];
    const lengthSquared = dx * dx + dy * dy;
    let position = lengthSquared === 0 ? 0 :
      ((point[0] - start[0]) * dx + (point[1] - start[1]) * dy) / lengthSquared;
    if (position < 0) position = 0;
    if (position > 1) position = 1;
    const gapX = point[0] - start[0] - position * dx;
    const gapY = point[1] - start[1] - position * dy;
    if (gapX * gapX + gapY * gapY < 1) {
      output[0] = point[0]; output[1] = point[1];
      return true;
    }
  }
  return false;
}

