export * from './load';
export * from './save';
export * from './save-middleware';

import {PrefsState} from '../../../prefs';

export async function load(): Promise<Partial<PrefsState>> {
	const serialized = window.localStorage.getItem('twine-prefs');
	const result: Partial<PrefsState> = {};

	if (!serialized) {
		return {};
	}

	serialized.split(',').forEach(id => {
		try {
			const serializedPref = window.localStorage.getItem(`twine-prefs-${id}`);

			if (!serializedPref) {
				console.warn(`No preference stored at twine-prefs-${id}`);
				return;
			}

			const item = JSON.parse(serializedPref);

			(result as any)[item.name] = item.value;
		} catch (e) {
			console.warn(
				`Preference ${id} had corrupt serialized value, skipping`,
				window.localStorage.getItem(`twine-prefs-${id}`),
				e
			);
		}
	});

	return result;
}

import {PrefsAction, PrefsState} from '../../../prefs';
import {save} from './save';

export function saveMiddleware(state: PrefsState, action: PrefsAction) {
	if (action.type === 'repair' || action.type === 'update') {
		save(state);
	}
}

import {v4 as uuid} from '@lukeed/uuid';
import {PrefsState} from '../../../prefs';

export function save(state: PrefsState) {
	// Delete existing prefs in local storage, since we aren't bothering to
	// preserve IDs.

	const previouslySerialized = window.localStorage.getItem('twine-prefs');

	if (previouslySerialized) {
		previouslySerialized.split(',').forEach(id => {
			window.localStorage.removeItem(`twine-prefs-${id}`);
		});
	}

	/* Save new ones. */

	const ids: string[] = [];

	for (const name in state) {
		const id = uuid();

		ids.push(id);
		window.localStorage.setItem(
			`twine-prefs-${id}`,
			JSON.stringify({
				id,
				name,
				value: state[name as keyof PrefsState]
			})
		);
	}

	window.localStorage.setItem('twine-prefs', ids.join(','));
}

