export * from './load';
export * from './save';
export * from './save-middleware';

import {passageDefaults, storyDefaults} from '../../../stories/defaults';
import {Passage, Story} from '../../../stories/stories.types';

/**
 * Parses initial state from local storage.
 */
export async function load(): Promise<Story[]> {
	const stories: Record<string, Story> = {};
	const serializedStories = window.localStorage.getItem('twine-stories');

	if (!serializedStories) {
		return [];
	}

	// First, deserialize stories. We index them by ID so that we can quickly add
	// passages to them as they are deserialized.

	serializedStories.split(',').forEach(id => {
		const serializedStory = window.localStorage.getItem(`twine-stories-${id}`);

		if (!serializedStory) {
			console.warn(
				`Story list contained ID ${id}, but twine-stories-${id} does not exist, skipping`
			);
			return;
		}

		try {
			const story: Story = JSON.parse(serializedStory);

			if (!story.id) {
				console.warn('Story in local storage had no ID, skipping', story);
				return;
			}

			stories[story.id] = {
				...storyDefaults(),
				...story,

				// Coerce lastUpdate to a date.
				lastUpdate: story.lastUpdate
					? new Date(Date.parse(story.lastUpdate as unknown as string))
					: new Date(),

				// Force the passages property to be an empty array -- we'll populate it
				// when we load passages below.
				passages: []
			};
		} catch (e) {
			console.warn(
				`Could not parse story as JSON, skipping: ${serializedStory}`
			);
		}
	});

	// Then create passages, adding them to their parent story.

	const serializedPassages = window.localStorage.getItem('twine-passages');

	if (serializedPassages) {
		serializedPassages.split(',').forEach(id => {
			const serializedPassage = window.localStorage.getItem(
				`twine-passages-${id}`
			);

			if (!serializedPassage) {
				console.warn(
					`Passage list contained ID ${id}, but twine-passages-${id} does not exist, skipping`
				);
				return;
			}

			try {
				const passage: Passage = JSON.parse(serializedPassage);

				if (!passage || !passage.story) {
					console.warn(
						`Passage ${id} did not have parent story ID, skipping`,
						passage
					);
					return;
				}

				if (!stories[passage.story]) {
					console.warn(
						`Passage ${id} is orphaned (looking for story ID ${passage.story}), skipping`
					);
					return;
				}

				stories[passage.story].passages.push({
					...passageDefaults,
					...passage,

					// Remove empty tags.
					tags: passage.tags ? passage.tags.filter(t => t.trim() !== '') : []
				});
			} catch (e) {
				console.warn(
					`Could not parse passage as JSON, skipping: ${serializedPassage}`
				);
			}
		});
	}

	// Flatten the stories object.
	return Object.values(stories);
}

import {
	passageWithId,
	passageWithName,
	StoriesAction,
	StoriesState,
	storyWithId,
	storyWithName
} from '../../../stories';
import {isPersistablePassageChange} from '../../persistable-changes';
import {
	deletePassageById,
	deleteStory,
	doUpdateTransaction,
	savePassage,
	saveStory
} from './save';

let lastState: StoriesState;

/**
 * A middleware function to save changes to local storage. This should be called
 * *after* the main reducer runs.
 */
export function saveMiddleware(state: StoriesState, action: StoriesAction) {
	switch (action.type) {
		case 'init':
		case 'repair':
			// We take no action here on a repair action. This is to prevent messing up a
			// story's last modified date. If the user then edits the story, we'll save
			// their change and the repair then.
			break;

		case 'createPassage': {
			if (!action.props.name) {
				throw new Error('Passage was created but with no name specified');
			}

			const story = storyWithId(state, action.storyId);
			const passage = passageWithName(state, story.id, action.props.name);

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);
				savePassage(transaction, passage);
			});
			break;
		}

		case 'createPassages': {
			const story = storyWithId(state, action.storyId);

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);
				for (const props of action.props) {
					if (!props.name) {
						throw new Error('Passage was created but with no name specified');
					}

					savePassage(
						transaction,
						passageWithName(state, story.id, props.name)
					);
				}
			});
			break;
		}

		case 'createStory': {
			if (!action.props.name) {
				throw new Error('Story was created but with no name specified');
			}

			const story = storyWithName(state, action.props.name);

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);

				for (const passage of story.passages) {
					savePassage(transaction, passage);
				}
			});
			break;
		}

		case 'deletePassage': {
			const story = storyWithId(state, action.storyId);

			// We can't dig up the passage in question right now, because
			// previousStories is only a shallow copy, and it's gone there at
			// this point in time.

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);
				deletePassageById(transaction, action.passageId);
			});
			break;
		}

		case 'deletePassages': {
			const story = storyWithId(state, action.storyId);

			// See above comment about passages.

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);

				for (const passageId of action.passageIds) {
					deletePassageById(transaction, passageId);
				}
			});
			break;
		}

		case 'deleteStory': {
			// The story will be gone from state by the time we're called, so we
			// need a cached copy.

			const story = storyWithId(lastState, action.storyId);

			doUpdateTransaction(transaction => {
				// We have to delete all passages, then the story itself.

				for (const passage of story.passages) {
					deletePassageById(transaction, passage.id);
				}

				deleteStory(transaction, story);
			});
			break;
		}

		case 'updatePassage':
			if (isPersistablePassageChange(action.props)) {
				const story = storyWithId(state, action.storyId);
				const passage = passageWithId(state, action.storyId, action.passageId);

				doUpdateTransaction(transaction => {
					saveStory(transaction, story);
					savePassage(transaction, passage);
				});
				break;
			}
			break;

		case 'updatePassages': {
			const story = storyWithId(state, action.storyId);

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);

				const passageIds = Object.keys(action.passageUpdates).filter(
					passageId =>
						isPersistablePassageChange(action.passageUpdates[passageId])
				);

				for (const passageId of passageIds) {
					savePassage(
						transaction,
						passageWithId(state, action.storyId, passageId)
					);
				}
			});
			break;
		}

		case 'updateStory': {
			const story = storyWithId(state, action.storyId);

			doUpdateTransaction(transaction => {
				saveStory(transaction, story);

				// Special case: if the passages property is being set, we need to
				// delete any passages there were in the story, but aren't anymore.

				if (action.props.passages) {
					const lastStory = storyWithId(lastState, action.storyId);

					for (const passage of lastStory.passages) {
						if (!action.props.passages.some(({id}) => id === passage.id)) {
							deletePassageById(transaction, passage.id);
						}
					}
				}

				story.passages.forEach(passage => savePassage(transaction, passage));
			});
			break;
		}

		default:
			console.warn(
				`Story action ${
					(action as any).type
				} has no local storage persistence handler`
			);
	}

	lastState = state;
}

// Functions for moving stories into local storage. This module in particular
// needs to remain well-optimized, as it has a direct effect on load time. As a
// result, saving requires that you start and end a transaction manually. This
// minimizes the number of writes to local storage.

import {Passage, Story} from '../../../stories/stories.types';
import {addUnique, remove} from '../comma-list';

export interface StorageTransaction {
	passageIds: string;
	storyIds: string;
}

export type StorageUpdater = (transaction: StorageTransaction) => void;

/**
 * A wrapper for a series of save/delete operations. This takes a function as
 * argument that will receive an object keeping track of the transaction. This
 * function should then make save and delete calls as necessary, passing the
 * provided transaction object as their first argument.
 */
export function doUpdateTransaction(updater: StorageUpdater) {
	const transaction = {
		passageIds: window.localStorage.getItem('twine-passages') ?? '',
		storyIds: window.localStorage.getItem('twine-stories') ?? ''
	};

	updater(transaction);

	window.localStorage.setItem('twine-stories', transaction.storyIds);
	window.localStorage.setItem('twine-passages', transaction.passageIds);
}

/**
 * Saves a story to local storage. This does *not* affect any child passages.
 **/
export function saveStory(transaction: StorageTransaction, story: Story) {
	if (!story.id) {
		throw new Error('Story has no ID');
	}

	transaction.storyIds = addUnique(transaction.storyIds, story.id);

	// We have to remove the passages property before serializing the story,
	// as those are serialized under separate keys.

	window.localStorage.setItem(
		`twine-stories-${story.id}`,
		JSON.stringify({...story, passages: undefined})
	);
}

/**
 * Deletes a story from local storage. This does *not* affect any child
 * passages. You *must* delete child passages manually.
 */
export function deleteStory(transaction: StorageTransaction, story: Story) {
	if (!story.id) {
		throw new Error('Story has no ID');
	}

	transaction.storyIds = remove(transaction.storyIds, story.id);
	window.localStorage.removeItem(`twine-stories-${story.id}`);
}

/**
 * Saves a passage to local storage.
 */
export function savePassage(transaction: StorageTransaction, passage: Passage) {
	if (!passage.id) {
		throw new Error('Passage has no ID');
	}

	transaction.passageIds = addUnique(transaction.passageIds, passage.id);
	window.localStorage.setItem(
		`twine-passages-${passage.id}`,
		JSON.stringify(passage)
	);
}

/**
 * Deletes a passage from local storage.
 */
export function deletePassage(
	transaction: StorageTransaction,
	passage: Passage
) {
	if (!passage.id) {
		throw new Error('Passage has no ID');
	}

	deletePassageById(transaction, passage.id);
}

/**
 * Deletes a passage from local storage by ID only.
 */
export function deletePassageById(
	transaction: StorageTransaction,
	passageId: string
) {
	transaction.passageIds = remove(transaction.passageIds, passageId);
	window.localStorage.removeItem(`twine-passages-${passageId}`);
}

export * from './load';
export * from './save';
export * from './save-middleware';

import {StoryFormatsState} from '../../../story-formats/story-formats.types';

export async function load(): Promise<StoryFormatsState> {
	const result: StoryFormatsState = [];
	const serialized = window.localStorage.getItem('twine-storyformats');

	if (!serialized) {
		return [];
	}

	serialized.split(',').forEach(id => {
		try {
			const serializedFormat = window.localStorage.getItem(
				`twine-storyformats-${id}`
			);

			if (!serializedFormat) {
				console.warn(
					`No story format stored at twine-storyformats-${id}, skipping`
				);
				return;
			}

			result.push({...JSON.parse(serializedFormat), loadState: 'unloaded'});
		} catch (e) {
			console.warn(
				`Story format ${id} had corrupt serialized value, skipping`,
				window.localStorage.getItem(`twine-storyformats-${id}`)
			);
		}
	});

	return result;
}

import {StoryFormatsAction, StoryFormatsState} from '../../../story-formats';
import {isPersistableStoryFormatChange} from '../../persistable-changes';
import {save} from './save';

/**
 * A middleware function to save changes to local storage. This should be called
 * *after* the main reducer runs.
 */
export function saveMiddleware(
	state: StoryFormatsState,
	action: StoryFormatsAction
) {
	switch (action.type) {
		case 'create':
		case 'delete':
		case 'repair':
			save(state);
			break;

		case 'update':
			// Is this a significant update?
			if (isPersistableStoryFormatChange(action.props)) {
				save(state);
			}
			break;
	}
}

import {v4 as uuid} from '@lukeed/uuid';
import {StoryFormatsState} from '../../../story-formats/story-formats.types';

export function save(state: StoryFormatsState) {
	// Delete existing formats in local storage, since we aren't bothering to
	// preserve ids.

	const previouslySerialized =
		window.localStorage.getItem('twine-storyformats');

	if (previouslySerialized) {
		previouslySerialized.split(',').forEach(id => {
			window.localStorage.removeItem(`twine-storyformats-${id}`);
		});
	}

	// Save new ones.

	const ids: string[] = [];

	for (const format of state) {
		const id = uuid();

		// We have to remove the `properties` property if it exists, as that is
		// dynamically added when loading.

		ids.push(id);
		window.localStorage.setItem(
			`twine-storyformats-${id}`,
			JSON.stringify({
				...format,
				loadError: undefined,
				loadState: undefined,
				properties: undefined,
				selected: undefined
			})
		);
	}

	window.localStorage.setItem('twine-storyformats', ids.join(','));
}

